<script setup lang="ts">
import OperatorTaskCharts from './OperatorTaskCharts.vue'
const props=defineProps<{warehouseId:number;start:string;end:string}>()
const {t,locale}=useI18n(),{bizErrorMessage}=useBizError()
const data=ref<any>(null),error=ref(''),loading=ref(false),page=ref(1),exporting=ref(''),table=ref(false),kind=ref<'picking'|'packing'>('picking'),highlight=ref('')
const taskOpen=ref(false),taskSelection=ref<{operatorId:number;name:string;day?:string}|null>(null),taskData=ref<any>(null),taskLoading=ref(false),taskError=ref(''),taskPage=ref(1)
let taskGeneration=0
const taskColumns=computed(()=>[{key:'task',label:t('operator-chart.task')},{key:'dn_id',label:t('dn.entity')},{key:'quantity',label:t('operator-report.quantity'),type:'qty' as const,keepZero:true},{key:'minutes',label:t('operator-chart.minutes')},{key:'completed_at',label:t('operator-overview.completed')}])
const loadTasks=async()=>{if(!taskSelection.value)return;const seq=++taskGeneration;taskLoading.value=true;taskError.value='';taskData.value=null;const result=await httpRequest<any>('/api/warehouse/picking/report/operators/tasks',{params:{operator_id:taskSelection.value.operatorId,start_date:taskSelection.value.day||props.start,end_date:taskSelection.value.day||props.end,page:taskPage.value,per_page:20},headers:warehouseHeaders(props.warehouseId),onError:e=>{if(seq===taskGeneration)taskError.value=bizErrorMessage(e)}});if(seq===taskGeneration){taskData.value=result;taskLoading.value=false}}
const openTasks=(selection:{operatorId:number;name:string;day?:string})=>{taskSelection.value=selection;highlight.value=String(selection.operatorId);taskPage.value=1;taskOpen.value=true;loadTasks()}
watch(taskOpen,value=>{if(!value)taskGeneration++})
const kinds=computed(()=>Object.keys(data.value?.phases||{}) as ('picking'|'packing')[])
const chartData=computed(()=>data.value?{...data.value,task_chart:data.value.phases[kind.value]?.task_chart||{items:[],total:0,untimed:0,median_per_hour:null}}:null)
const untimed=computed(()=>kinds.value.reduce((n,k)=>n+data.value.phases[k].task_chart.untimed,0))
const format=(n:number|null|undefined)=>n==null?'—':n.toLocaleString(locale.value,{maximumFractionDigits:1})
const rate=(k:string)=>{const s=data.value.phases[k].summary;return s.seconds?s.timed_quantity*3600/s.seconds:null}
const rateMax=computed(()=>Math.max(60,Math.ceil((data.value?.scales.rate||1)/60)*60))
let generation=0
const load=async()=>{const seq=++generation;loading.value=true;error.value='';data.value=null;const result=await httpRequest<any>('/api/warehouse/picking/report/operators/overview',{params:{start_date:props.start,end_date:props.end,page:page.value,per_page:50},headers:warehouseHeaders(props.warehouseId),onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq!==generation)return;data.value=result;loading.value=false;if(result&&!result.phases[kind.value])kind.value=Object.keys(result.phases)[0] as 'picking'|'packing'}
watch(()=>[props.warehouseId,props.start,props.end],()=>{page.value=1;highlight.value='';taskOpen.value=false;load()});onMounted(load);onBeforeUnmount(()=>{generation++;taskGeneration++})
const download=async(k:string)=>{if(exporting.value)return;exporting.value=k;try{await downloadFile(`/api/warehouse/${k}/report/operators/export?`+new URLSearchParams({start_date:props.start,end_date:props.end}),{headers:warehouseHeaders(props.warehouseId)},k+'-operators.csv')}catch(e){error.value=bizErrorMessage(e as HttpRequestError)}finally{exporting.value=''}}
</script>
<template><div class="operator-overview"><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="load">{{t('dn.list.retry')}}</WButton></template></WAlert><WEmptyState v-if="loading" :title="t('common.status.loading')"/>
<template v-if="data"><div class="metrics" :style="{gridTemplateColumns:'repeat('+Math.max(1,kinds.length*2+1)+',minmax(0,1fr))'}"><template v-for="phase in kinds" :key="phase"><WCard><span>{{t('nav.'+phase)}}</span><strong>{{format(data.phases[phase].summary.quantity)}}</strong><small>{{format(data.phases[phase].summary.tasks)}} {{t('operator-report.tasks')}} · {{format(data.phases[phase].summary.seconds/3600)}} {{t('operator-overview.hours')}}</small></WCard><WCard><span>{{t('nav.'+phase)}} · {{t('operator-report.rate')}}</span><strong>{{format(rate(phase))}}</strong><small>{{t('operator-chart.task-median')}} {{format(data.phases[phase].task_chart.median_per_hour)}}</small></WCard></template><WCard><span :class="{attention:untimed>0}">{{t('operator-report.untimed')}}</span><strong>{{format(untimed)}}</strong><small>{{t('operator-overview.untimed-help')}}</small></WCard></div>
<WCard flush><div class="overview-header"><h2>{{t('operator-overview.by-person')}} <WHelp :text="t('operator-report.scope')"/></h2><div class="legend"><span><i class="bar-key"/>{{t('operator-report.quantity')}}</span><span><i class="dot-key"/>{{t('operator-report.rate')}}</span><span><i class="median-key"/>{{t('operator-chart.task-median')}}</span><WButton variant="text" size="sm" @click="table=!table">{{t(table?'operator-chart.chart':'operator-chart.table')}}</WButton><WButton v-for="phase in kinds" :key="phase" size="sm" icon="download" :loading="exporting===phase" :disabled="!!exporting" @click="download(phase)">{{t('nav.'+phase)}} CSV</WButton></div></div>
<div class="overview-scroll"><table class="people"><thead><tr><th>{{t('operator-report.operator')}}</th><template v-for="phase in kinds" :key="phase"><th class="phase-start">{{t('nav.'+phase)}} · {{t('operator-report.quantity')}}</th><th>{{t('nav.'+phase)}} · {{t('operator-report.rate')}}</th></template></tr><tr v-if="!table" class="axis"><th/><template v-for="phase in kinds" :key="phase"><th class="phase-start"/><th><div class="rate-grid"><div class="ticks"><span v-for="i in 4" :key="i" :style="{left:(i-1)*100/3+'%'}">{{format(rateMax*(i-1)/3)}}</span></div><small>{{t('operator-overview.units-hour')}}</small></div></th></template></tr></thead><tbody><tr v-for="person in data.items" :key="person.operator_id" :class="{'is-highlight':highlight===String(person.operator_id)}"><td><button class="person" :aria-pressed="highlight===String(person.operator_id)" @click="openTasks({operatorId:person.operator_id,name:person.name})"><i>{{Array.from(String(person.name))[0]}}</i><span>{{person.name}}</span></button></td><template v-for="phase in kinds" :key="phase"><td class="phase-start"><div v-if="person.phases[phase]" class="quantity-grid" :class="{plain:table}"><span v-if="!table" class="quantity-track"><i :style="{width:person.phases[phase].quantity*100/data.scales.quantity+'%'}"/></span><span>{{format(person.phases[phase].quantity)}}<small>{{format(person.phases[phase].tasks)}} {{t('operator-report.tasks')}} · {{format(person.phases[phase].seconds/3600)}} {{t('operator-overview.hours')}}</small></span></div></td><td><div v-if="person.phases[phase]?.per_hour!=null" class="rate-grid" :class="{plain:table}"><span v-if="!table" class="rate-track"><i v-if="data.phases[phase].task_chart.median_per_hour!=null" class="median" :style="{left:data.phases[phase].task_chart.median_per_hour*100/rateMax+'%'}"/><b :style="{left:person.phases[phase].per_hour*100/rateMax+'%'}"/></span><strong>{{format(person.phases[phase].per_hour)}}</strong></div><span v-else-if="person.phases[phase]">—</span></td></template></tr><tr v-if="!data.items.length"><td :colspan="1+kinds.length*2" class="empty">{{t('w.table.empty')}}</td></tr></tbody></table></div><template #footer><WPagination :page="page" :page-size="50" :total="data.total" show-total @update:page="value=>{page=value;load()}"/></template></WCard>
<OperatorTaskCharts v-if="kinds.length" class="standalone-charts" :data="chartData" :kind="kind" :highlight-operator="highlight" @drilldown="openTasks"><template #phase-control><div class="phase-control" role="radiogroup" :aria-label="t('operator-overview.phase')"><button v-for="phase in kinds" :key="phase" type="button" role="radio" :aria-checked="kind===phase" @click="kind=phase">{{t('nav.'+phase)}} {{data.phases[phase].summary.tasks}}</button></div></template></OperatorTaskCharts>
</template><WDrawer v-model:open="taskOpen" :title="(taskSelection?.name||'')+' · '+(taskSelection?.day||props.start+' – '+props.end)" width="760px"><p class="drill-help">{{t('operator-overview.task-help')}}</p><WAlert v-if="taskError" tone="block" :title="taskError"><template #actions><WButton @click="loadTasks">{{t('dn.list.retry')}}</WButton></template></WAlert><WTable :rows="taskData?.items||[]" :columns="taskColumns" :loading="taskLoading" :row-key="(row:any)=>row.kind+'-'+row.id"><template #cell-task="{row}"><NuxtLink :to="'/'+row.kind+'/detail/'+row.id">{{t('nav.'+row.kind)}} #{{row.id}}</NuxtLink></template><template #cell-dn_id="{row}">DN-{{row.dn_id}}</template><template #cell-minutes="{row}">{{row.seconds==null?'—':format(row.seconds/60)}}</template><template #cell-completed_at="{row}">{{$dayjs(row.completed_at,'MM/DD HH:mm',{timezone:taskData.timezone})}}</template></WTable><template #footer><WPagination :page="taskPage" :page-size="20" :total="taskData?.total" show-total @update:page="value=>{taskPage=value;loadTasks()}"/></template></WDrawer></div></template>
<style scoped>
.drill-help{font-size:12px;line-height:18px;color:var(--w-text-3);margin:0 0 12px}.operator-overview{display:flex;flex-direction:column;gap:16px}.metrics{display:grid;gap:16px}.metrics :deep(.w-card__body){padding:16px;display:flex;flex-direction:column;gap:2px}.metrics span{font-size:12px;line-height:18px;color:var(--w-text-2);font-weight:500}.metrics strong{font-size:20px;line-height:28px;font-weight:600}small{display:block;font-size:12px;line-height:18px;color:var(--w-text-3)}.attention:before{content:'';display:inline-block;width:6px;height:6px;background:#E99B1A;border-radius:50%;margin-right:6px}.overview-header{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;padding:16px 24px 12px}h2{margin:0;display:flex;align-items:center;gap:6px;font-size:16px;line-height:24px;font-weight:600}.legend{display:flex;align-items:center;flex-wrap:wrap;gap:16px;font-size:12px;color:var(--w-text-2)}.legend>span{display:flex;align-items:center;gap:6px}.legend i{display:inline-block;background:#7855FE;width:8px;height:8px}.legend .bar-key{border-radius:2px}.legend .dot-key{border-radius:50%}.legend .median-key{width:2px;height:12px;background:#A0A4B0}.overview-scroll{overflow:auto}.people{width:100%;border-collapse:collapse;min-width:960px;font-size:13px;line-height:20px}th{text-align:left;font-weight:500;font-size:12px;line-height:18px;color:var(--w-text-3);padding:8px 12px 2px}th:first-child,td:first-child{padding-left:24px;min-width:180px}th:last-child,td:last-child{padding-right:24px}thead{border-bottom:1px solid var(--w-border)}td{padding:10px 12px;border-top:1px solid var(--w-line)}.phase-start{border-left:1px solid var(--w-line)}.axis th{padding-top:4px;padding-bottom:6px}.rate-grid{display:grid;grid-template-columns:minmax(80px,1fr) 64px;gap:10px;align-items:center}.rate-grid>strong{text-align:right;font-weight:600}.ticks{height:18px;position:relative}.ticks>span{position:absolute;transform:translateX(-50%)}.rate-grid small{text-align:right}.quantity-grid{display:grid;grid-template-columns:minmax(60px,1fr) 132px;gap:10px;align-items:center}.quantity-track{height:12px;position:relative}.quantity-track i{display:block;height:100%;background:#7855FE;border-radius:0 4px 4px 0}.rate-track{position:relative;height:28px}.rate-track:before{content:'';position:absolute;top:13px;height:2px;background:var(--w-line);left:0;right:0}.median{position:absolute;top:3px;height:22px;width:2px;margin-left:-1px;background:#A0A4B0}.rate-track b{position:absolute;top:8px;width:12px;height:12px;margin-left:-6px;border-radius:50%;background:#7855FE;border:2px solid white;box-shadow:0 0 0 1px #7855FE}.person{display:flex;align-items:center;gap:10px;border:0;background:transparent;text-align:left;font:inherit;color:inherit;cursor:pointer}.person i{font-style:normal;width:28px;height:28px;display:grid;place-items:center;border-radius:50%;background:var(--w-line);flex:none}.person span{max-width:160px;overflow-wrap:anywhere;font-weight:500}.is-highlight{background:var(--w-sel-soft)}.plain{display:block}.plain strong{display:block;text-align:right}.empty{text-align:center;color:var(--w-text-3);padding:32px}.standalone-charts{margin:0}.phase-control{display:inline-flex;align-self:flex-start;gap:2px;padding:2px;border-radius:6px;background:var(--w-line)}.phase-control button{height:28px;padding:0 12px;border:0;border-radius:6px;background:transparent;color:var(--w-text-2);font:inherit;font-size:13px;cursor:pointer}.phase-control button[aria-checked=true]{background:white;color:var(--w-text-1);box-shadow:0 1px 2px #10121b1a;font-weight:600}@media(max-width:1000px){.metrics{grid-template-columns:repeat(3,minmax(0,1fr))!important}}@media(max-width:600px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))!important}.standalone-charts{margin:0}}
</style>
